136	    /**
137	     * Normalise a raw telephone number to E.164 form.
138	     *
139	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
140	     * code are kept when present; otherwise country code '+61' is assumed and a
141	     * single leading '0' is dropped from the national digits. The result must have
142	     * between 8 and 15 digits after the '+'.
143	     *
144	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
145	     * national-number length is additionally validated against that country code:
146	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
147	     * length is wrong for its country is rejected.
148	     *
149	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
150	     */
151	    static String toE164(String raw) {
152	        if (raw == null) {
153	            return null;
154	        }
155	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
156	        String digits;
157	        boolean explicitCountryCode;
158	        if (cleaned.startsWith("+")) {
159	            digits = cleaned.substring(1);
160	            explicitCountryCode = true;
161	        } else {
162	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
163	            digits = "61" + national;
164	            explicitCountryCode = false;
165	        }
166	        if (!digits.matches("[0-9]{8,15}")) {
167	            return null;
168	        }
169	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
170	            return null;
171	        }
172	        return "+" + digits;
173	    }
174	
175	    /**
176	     * Validate the national-number length of an E.164 number (its digits without the
177	     * leading '+') against the requirement for its country code: country code '+61'
178	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
179	     * without a configured length requirement are accepted unchanged.
180	     */
181	    private static boolean hasValidNationalLength(String digits) {
182	        if (digits.startsWith("61")) {
183	            return digits.length() - "61".length() == 9;
184	        }
185	        if (digits.startsWith("1")) {
186	            return digits.length() - "1".length() == 10;
187	        }
188	        return true;
189	    }
190	
191	    /**
192	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
193	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
194	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
195	     * input normalises to the empty string.
196	     */
197	    private static String normaliseIdentity(String value) {
198	        if (value == null) {
199	            return "";
200	        }
201	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
202	    }
203	
204	    /**
205	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
206	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
207	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
208	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
209	     * that is both stored and used for every address comparison.
210	     */
211	    static String normaliseAddress(String value) {
212	        if (value == null) {
213	            return "";
214	        }
215	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
216	        if (collapsed.isEmpty()) {
217	            return "";
218	        }
219	        String[] tokens = collapsed.split(" ");
220	        StringBuilder result = new StringBuilder();
221	        for (int i = 0; i < tokens.length; i++) {
222	            if (i > 0) {
223	                result.append(' ');
224	            }
225	            result.append(expandAddressAbbreviation(tokens[i]));
226	        }
227	        return result.toString();
228	    }
229	
230	    /**
231	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
232	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
233	     * returned unchanged.
234	     */
235	    private static String expandAddressAbbreviation(String token) {
236	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
237	        return switch (core) {
238	            case "ST" -> "STREET";
239	            case "RD" -> "ROAD";
240	            case "AVE" -> "AVENUE";
241	            default -> token;
242	        };
243	    }
244	
245	    /**
246	     * Derive the stable, shared household identifier for owners in the same household: the first 12
247	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
248	     * so every owner with the same last name and postcode resolves to the same value regardless of
249	     * the order in which they were created.
250	     */
251	    private static String householdId(String lastNameKey, String postcode) {
252	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
253	    }
254	
255	    /**
256	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
257	     * name and postcode). An owner without a postcode has no household peers and counts as a household
258	     * of one.
259	     */
260	    private int householdSize(Owner owner) {
261	        if (owner.getPostcode() == null) {
262	            return 1;
263	        }
264	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
265	        return (int) this.clinicService.findAllOwners().stream()
266	            .filter(existing -> existing.getPostcode() != null
267	                && householdId.equals(
268	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
269	            .count();
270	    }
271	
272	    /**
273	     * The existing, non-deleted owners that belong to {@code owner}'s household (sharing its
274	     * normalized last name and postcode), excluding {@code owner} itself. An owner without a
275	     * postcode has no household peers, so this is empty.
276	     */
277	    private List<Owner> otherHouseholdMembers(Owner owner) {
278	        if (owner.getPostcode() == null) {
279	            return List.of();
280	        }
281	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
282	        return this.clinicService.findAllOwners().stream()
283	            .filter(existing -> !existing.isDeleted())
284	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
285	            .filter(existing -> existing.getPostcode() != null
286	                && householdId.equals(
287	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
288	            .toList();
289	    }
290	
291	    /**
292	     * The owner's membership level after applying the household ceiling: the natural level derived
293	     * from the owner's membership points, capped at one above the current maximum membership level
294	     * among the owner's existing household members. With no existing household member no cap applies.
295	     * Assumes the owner's household size has already been populated.
296	     */
297	    private Integer cappedMembershipLevel(Owner owner) {
298	        Integer natural = ownerMapper.formatMembershipLevel(owner);
299	        if (natural == null) {
300	            return null;
301	        }
302	        List<Owner> members = otherHouseholdMembers(owner);
303	        if (members.isEmpty()) {
304	            return natural;
305	        }
306	        int maxMemberLevel = 0;
307	        for (Owner member : members) {
308	            member.setHouseholdSize(householdSize(member));
309	            Integer memberLevel = ownerMapper.formatMembershipLevel(member);
310	            if (memberLevel != null) {
311	                maxMemberLevel = Math.max(maxMemberLevel, memberLevel);
312	            }
313	        }
314	        return Math.min(natural, maxMemberLevel + 1);
315	    }
316	
317	    /**
318	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
319	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
320	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
321	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
322	     * only on the owner's own region and identity, not on how many owners already exist.
323	     */
324	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
325	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
326	    }
327	
328	    /**
329	     * De-duplicate a computed customer code against the codes already assigned to existing owners:
330	     * when {@code code} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
331	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
332	     */
333	    private String deduplicateCustomerCode(String code) {
334	        Set<String> existing = this.clinicService.findAllOwners().stream()
335	            .map(Owner::getCustomerCode)
336	            .filter(Objects::nonNull)
337	            .collect(Collectors.toSet());
338	        if (!existing.contains(code)) {
339	            return code;
340	        }
341	        int n = 2;
342	        while (existing.contains(code + "-" + n)) {
343	            n++;
344	        }
345	        return code + "-" + n;
346	    }
347	
348	    /**
349	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
350	     */
351	    private static String hash8(String input) {
352	        return hashHex(input, 8, true);
353	    }
354	
355	    /**
356	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
357	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
358	     */
359	    private static String hashHex(String input, int length, boolean upperCase) {
360	        try {
361	            byte[] digest = MessageDigest.getInstance("SHA-256")
362	                .digest(input.getBytes(StandardCharsets.UTF_8));
363	            StringBuilder sb = new StringBuilder(digest.length * 2);
364	            for (byte b : digest) {
365	                sb.append(String.format("%02x", b));
366	            }
367	            String hex = sb.substring(0, length);
368	            return upperCase ? hex.toUpperCase() : hex;
369	        }
370	        catch (java.security.NoSuchAlgorithmException e) {
371	            throw new IllegalStateException(e);
372	        }
373	    }
374	
375	    /**
376	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
377	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
378	     * fixed city-to-region table, else {@code "UNKNOWN"}.
379	     */
380	    private static String region(String postcode, String city) {
381	        String fromPostcode = regionForPostcode(postcode);
382	        return fromPostcode != null ? fromPostcode : regionForCity(city);
383	    }
384	
385	    /**
386	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
387	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
388	     */
389	    private static String regionForPostcode(String postcode) {
390	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
391	            return null;
392	        }
393	        int value = Integer.parseInt(postcode);
394	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
395	            int[] range = entry.getValue();
396	            if (value >= range[0] && value <= range[1]) {
397	                return entry.getKey();
398	            }
399	        }
400	        return null;
401	    }
402	
403	    /**
404	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
405	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
406	     * weekday; ordinary weekday dates are returned unchanged.
407	     */
408	    static LocalDate toBusinessDay(LocalDate date) {
409	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
410	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
411	            || PUBLIC_HOLIDAYS.contains(date)) {
412	            date = date.plusDays(1);
413	        }
414	        return date;
415	    }
416	
417	    /**
418	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
419	     * using the same per-day accumulation path as the daily create-limit rule.
420	     */
421	    private long ownersCreatedOn(LocalDate registrationDate) {
422	        LocalDate day = toBusinessDay(registrationDate);
423	        return this.clinicService.findAllOwners().stream()
424	            .map(Owner::getRegistrationDate)
425	            .filter(existing -> existing != null)
426	            .map(OwnerRestControllerV1::toBusinessDay)
427	            .filter(day::equals)
428	            .count();
429	    }
430	
431	    /**
432	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
433	     * postcode against the owner's city region.
434	     */
435	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
436	        "NSW", new int[] {2000, 2099},
437	        "VIC", new int[] {3000, 3099},
438	        "QLD", new int[] {4000, 4099});
439	
440	    /**
441	     * Resolve an owner's region from the city using the fixed city-to-region table
442	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
443	     * when the city is not listed.
444	     */
445	    private static String regionForCity(String city) {
446	        return switch (city == null ? "" : city) {
447	            case "Sydney" -> "NSW";
448	            case "Melbourne" -> "VIC";
449	            case "Brisbane" -> "QLD";
450	            default -> "UNKNOWN";
451	        };
452	    }
453	
454	    /**
455	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
456	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
457	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
458	     */
459	    private static boolean isPostcodeValid(String postcode, String city) {
460	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
461	            return false;
462	        }
463	        int[] range = REGION_POSTCODES.get(regionForCity(city));
464	        if (range == null) {
465	            return true;
466	        }
467	        int value = Integer.parseInt(postcode);
468	        return value >= range[0] && value <= range[1];
469	    }
470	
471	    /**
472	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
473	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
474	     */
475	    private static boolean isDisposableEmailDomain(String email) {
476	        if (email == null) {
477	            return false;
478	        }
479	        int at = email.lastIndexOf('@');
480	        if (at < 0 || at == email.length() - 1) {
481	            return false;
482	        }
483	        String domain = email.substring(at + 1).toLowerCase();
484	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
485	    }
486	
487	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
488	    @Override
489	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
490	        Collection<Owner> owners;
491	        if (lastName != null) {
492	            owners = this.clinicService.findOwnerByLastName(lastName);
493	        } else {
494	            owners = this.clinicService.findAllOwners();
495	        }
496	        if (owners.isEmpty()) {
497	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
498	        }
499	        owners.forEach(owner -> owner.setHouseholdSize(householdSize(owner)));
500	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
501	    }
502	
503	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
504	    @Override
505	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
506	        Owner owner = this.clinicService.findOwnerById(ownerId);
507	        if (owner == null) {
508	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
509	        }
510	        owner.setHouseholdSize(householdSize(owner));
511	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
512	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
513	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
514	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
515	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
516	    }
517	
518	    /**
519	     * The value of the {@code Idempotency-Key} header on the current request, or {@code null} when the
520	     * request carries no such header (or there is no active servlet request). A blank value is treated
521	     * as absent.
522	     */
523	    private static String currentIdempotencyKey() {
524	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
525	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
526	            return null;
527	        }
528	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
529	        return (key == null || key.isBlank()) ? null : key;
530	    }
531	
532	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
533	    @Override
534	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
535	        String idempotencyKey = currentIdempotencyKey();
536	        if (idempotencyKey != null) {
537	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
538	            if (existingId != null) {
539	                Owner existing = this.clinicService.findOwnerById(existingId);
540	                if (existing != null) {
541	                    existing.setHouseholdSize(householdSize(existing));
542	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
543	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
544	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
545	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
546	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
547	                }
548	            }
549	        }
550	        String telephone = toE164(ownerFieldsDto.getTelephone());
551	        if (telephone == null) {
552	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
553	        }
554	        String email = ownerFieldsDto.getEmail();
555	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
556	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
557	        }
558	        if (isDisposableEmailDomain(email)) {
559	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
560	        }
561	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
562	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
563	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
564	        // normalized addressLine2 appended after a single space when present.
565	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
566	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
567	        boolean structuredAddress = !addressLine1.isEmpty();
568	        String address;
569	        if (structuredAddress) {
570	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
571	        } else {
572	            address = normaliseAddress(ownerFieldsDto.getAddress());
573	        }
574	        if (address.isEmpty()) {
575	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
576	        }
577	        String postcode = ownerFieldsDto.getPostcode();
578	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
579	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
580	        }
581	        if (ownerFieldsDto.getRegistrationDate() != null
582	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
583	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
584	        }
585	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
586	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
587	        LocalDate registrationDate = toBusinessDay(effectiveDate);
588	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
589	            .map(Owner::getRegistrationDate)
590	            .filter(existing -> existing != null)
591	            .map(OwnerRestControllerV1::toBusinessDay)
592	            .filter(registrationDate::equals)
593	            .count();
594	        if (ownersCreatedThatDay >= 100) {
595	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
596	        }
597	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
598	        long ownersInCity = this.clinicService.findAllOwners().stream()
599	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
600	            .count();
601	        if (ownersInCity >= 50) {
602	            return new ResponseEntity<>(HttpStatus.CONFLICT);
603	        }
604	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
605	        // The household is deterministically keyed on (normalized last name, postcode): every owner
606	        // with a postcode belongs to the household identified by this computed id, and owners sharing
607	        // a last name and postcode share it automatically. A new owner may join an existing household;
608	        // the household ceiling below (rather than a hard rejection) governs its membership level.
609	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
610	        // Duplicate detection is the single identity key (normalized telephone, lower-cased email and
611	        // Soundex of the last name). A candidate whose key collides with an existing, non-deleted
612	        // owner is a hard duplicate (409); the household id no longer participates in this decision.
613	        String identityKey = OwnerIdentity.identityKey(telephone, email, ownerFieldsDto.getLastName());
614	        boolean identityInUse = this.clinicService.findAllOwners().stream()
615	            .filter(existing -> !existing.isDeleted())
616	            .anyMatch(existing -> OwnerIdentity.identityKey(toE164(existing.getTelephone()),
617	                existing.getEmail(), existing.getLastName()).equals(identityKey));
618	        if (identityInUse) {
619	            return new ResponseEntity<>(HttpStatus.CONFLICT);
620	        }
621	        // Soft match: an existing, non-deleted owner sharing this owner's postcode and last-name
622	        // Soundex but with a different identity key (e.g. a different telephone) is not a hard
623	        // duplicate, but the new owner is flagged as a possible duplicate of it.
624	        String lastNameSoundex = OwnerIdentity.soundex(ownerFieldsDto.getLastName());
625	        Integer possibleDuplicateOf = (postcode == null) ? null
626	            : this.clinicService.findAllOwners().stream()
627	                .filter(existing -> !existing.isDeleted())
628	                .filter(existing -> postcode.equals(existing.getPostcode()))
629	                .filter(existing -> lastNameSoundex.equals(OwnerIdentity.soundex(existing.getLastName())))
630	                .filter(existing -> !OwnerIdentity.identityKey(toE164(existing.getTelephone()),
631	                    existing.getEmail(), existing.getLastName()).equals(identityKey))
632	                .map(Owner::getId)
633	                .findFirst()
634	                .orElse(null);
635	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
636	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
637	            .filter(existing ->
638	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
639	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
640	            .count();
641	        HttpHeaders headers = new HttpHeaders();
642	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
643	        owner.setNamesakeCount(namesakeCount);
644	        owner.setAddress(address);
645	        if (structuredAddress) {
646	            owner.setAddressLine1(addressLine1);
647	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
648	        } else {
649	            owner.setAddressLine1(null);
650	            owner.setAddressLine2(null);
651	        }
652	        owner.setTelephone(telephone);
653	        owner.setEmail(email == null ? null : email.toLowerCase());
654	        owner.setRegistrationDate(registrationDate);
655	        owner.setCustomerCode(deduplicateCustomerCode(nextCustomerCode(
656	            region(postcode, owner.getCity()), telephone, owner.getLastName())));
657	        owner.setHouseholdId(householdId);
658	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
659	        this.clinicService.saveOwner(owner);
660	        if (idempotencyKey != null) {
661	            this.idempotentCreations.put(idempotencyKey, owner.getId());
662	        }
663	        owner.setHouseholdSize(householdSize(owner));
664	        Integer membershipLevel = cappedMembershipLevel(owner);
665	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
666	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
667	            membershipLevel, ownerMapper.formatMembershipNumber(owner));
668	        // Immutable structured event carrying the owner's current primary identifier (the
669	        // customerCode today; the memberId once the two are unified), with a monotonic sequence.
670	        AUDIT.info(new OwnerCreatedEvent(CREATE_SEQUENCE.incrementAndGet(), owner.getId(),
671	            owner.getCustomerCode(), membershipLevel).toJson());
672	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
673	        ownerDto.setMembershipLevel(membershipLevel);
674	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
675	        headers.setLocation(UriComponentsBuilder.newInstance()
676	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
677	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
678	    }
679	
680	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
681	    @Override
682	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
683	        String telephone = toE164(ownerFieldsDto.getTelephone());
684	        if (telephone == null) {
685	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
686	        }
687	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
688	        if (currentOwner == null) {
689	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
690	        }
691	        String email = ownerFieldsDto.getEmail();
692	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
693	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
694	        }
695	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
696	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
697	        if (!addressLine1.isEmpty()) {
698	            currentOwner.setAddressLine1(addressLine1);
699	            currentOwner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
700	            currentOwner.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
701	        } else {
702	            currentOwner.setAddressLine1(null);
703	            currentOwner.setAddressLine2(null);
704	            currentOwner.setAddress(normaliseAddress(ownerFieldsDto.getAddress()));
705	        }
706	        currentOwner.setCity(ownerFieldsDto.getCity());
707	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
708	        currentOwner.setLastName(ownerFieldsDto.getLastName());
709	        currentOwner.setTelephone(telephone);
710	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
711	        this.clinicService.saveOwner(currentOwner);
712	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
713	    }
714	
