44	     * (falling back to the current date when the registration date is absent): {@code MINOR} when
45	     * under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Returns
46	     * {@code null} when no birth date is present, so the field is omitted from the response.
47	     */
48	    default OwnerDto.AgeBandEnum formatAgeBand(Owner owner) {
49	        if (owner == null || owner.getBirthDate() == null) {
50	            return null;
51	        }
52	        LocalDate asOf = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
53	        int age = Period.between(owner.getBirthDate(), asOf).getYears();
54	        if (age < 18) {
55	            return OwnerDto.AgeBandEnum.MINOR;
56	        }
57	        if (age < 65) {
58	            return OwnerDto.AgeBandEnum.ADULT;
59	        }
60	        return OwnerDto.AgeBandEnum.SENIOR;
61	    }
62	
63	    /**
64	     * Derives an owner's duplicate-detection identity key as the lower-case SHA-256 hex digest over
65	     * {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'} from the stored (already
66	     * E.164-normalized) telephone, lower-cased email and the Soundex code of the last name. A
67	     * {@code null} telephone or email contributes the empty string in its position.
68	     */
69	    default String formatIdentityKey(Owner owner) {
70	        if (owner == null) {
71	            return null;
72	        }
73	        return org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(
74	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
75	    }
76	
77	    /**
78	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
79	     * (non-null and non-blank), otherwise {@code PHONE}.
80	     */
81	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
82	        if (owner == null) {
83	            return null;
84	        }
85	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
86	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
87	    }
88	
89	    /**
90	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
91	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
92	     * When the customer code is absent it falls back to resolving the region directly, preferring the
93	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
94	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
95	     * {@code "UNKNOWN"} when neither resolves.
96	     */
97	    default String formatLocality(Owner owner) {
98	        if (owner == null) {
99	            return null;
100	        }
101	        String code = owner.getCustomerCode();
102	        if (code != null) {
103	            int dash = code.indexOf('-');
104	            if (dash > 0) {
105	                return code.substring(0, dash);
106	            }
107	        }
108	        String fromPostcode = regionForPostcode(owner.getPostcode());
109	        if (fromPostcode != null) {
110	            return fromPostcode;
111	        }
112	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
113	            case "Sydney" -> "NSW";
114	            case "Melbourne" -> "VIC";
115	            case "Brisbane" -> "QLD";
116	            default -> "UNKNOWN";
117	        };
118	    }
119	
120	    /**
121	     * Derives an owner's IANA timezone from the locality (region) via the fixed region-to-timezone
122	     * table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
123	     * {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not one of these,
124	     * so the field is omitted from the response.
125	     */
126	    default String formatTimezone(Owner owner) {
127	        if (owner == null) {
128	            return null;
129	        }
130	        return switch (formatLocality(owner)) {
131	            case "NSW" -> "Australia/Sydney";
132	            case "VIC" -> "Australia/Melbourne";
133	            case "QLD" -> "Australia/Brisbane";
134	            default -> null;
135	        };
136	    }
137	
138	    /**
139	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
140	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
141	     * no known range, signalling that the caller should fall back to the city-to-region table.
142	     */
143	    private String regionForPostcode(String postcode) {
144	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
145	            return null;
146	        }
147	        int value = Integer.parseInt(postcode);
148	        if (value >= 2000 && value <= 2099) {
149	            return "NSW";
150	        }
151	        if (value >= 3000 && value <= 3099) {
152	            return "VIC";
153	        }
154	        if (value >= 4000 && value <= 4099) {
155	            return "QLD";
156	        }
157	        return null;
158	    }
159	
160	    /**
161	     * Computes an owner's membership points, starting at 0: plus 2 when an email is present, plus 1
162	     * when the owner's namesake count is 0, plus 2 for a household of 3 or more, plus 3 when the
163	     * owner's tenure exceeds 365 days.
164	     */
165	    default Integer formatMembershipPoints(Owner owner) {
166	        if (owner == null) {
167	            return null;
168	        }
169	        int points = 0;
170	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
171	        if (hasEmail) {
172	            points += 2;
173	        }
174	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
175	        if (unique) {
176	            points += 1;
177	        }
178	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
179	        if (largeHousehold) {
180	            points += 2;
181	        }
182	        boolean tenured = owner.getRegistrationDate() != null
183	            && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1;
184	        if (tenured) {
185	            points += 3;
186	        }
187	        return points;
188	    }
189	
190	    /**
191	     * Derives an owner's membership level, a number from 1 to 4, from the owner's membership points:
192	     * 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
193	     */
194	    default Integer formatMembershipLevel(Owner owner) {
195	        if (owner == null) {
196	            return null;
197	        }
198	        int points = formatMembershipPoints(owner);
199	        if (points <= 1) {
200	            return 1;
201	        }
202	        if (points <= 3) {
203	            return 2;
204	        }
205	        if (points <= 5) {
206	            return 3;
207	        }
208	        return 4;
209	    }
210	
211	    /**
212	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
213	     * customer code. Returns {@code null} when the customer code is absent.
214	     */
215	    default Integer formatCheckDigit(Owner owner) {
216	        if (owner == null || owner.getCustomerCode() == null) {
217	            return null;
218	        }
219	        String code = owner.getCustomerCode();
220	        int sum = 0;
221	        boolean dbl = true;
222	        for (int i = code.length() - 1; i >= 0; i--) {
223	            char c = code.charAt(i);
224	            if (c < '0' || c > '9') {
225	                continue;
226	            }
227	            int d = c - '0';
228	            if (dbl) {
229	                d *= 2;
230	                if (d > 9) {
231	                    d -= 9;
232	                }
233	            }
234	            sum += d;
235	            dbl = !dbl;
236	        }
237	        return (10 - (sum % 10)) % 10;
238	    }
239	
240	    /**
241	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
242	     * digits of the fiscal year (starting 1 July) of the business-day-adjusted registration date
243	     * (e.g. {@code "NSW-1A2B3C4D-M26"}). Returns {@code null} when the customer code or registration
244	     * date is absent.
245	     */
246	    default String formatMembershipNumber(Owner owner) {
247	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
248	            return null;
249	        }
250	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearStart(owner.getRegistrationDate()) % 100);
251	    }
252	
253	    /**
254	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, where YY is the last two digits of the
255	     * starting calendar year of the fiscal year (starting 1 July) that contains the owner's
256	     * business-day-adjusted registration date (e.g. 5 August 2026 yields {@code "FY26"} and 3 March
257	     * 2026 yields {@code "FY25"}). Returns {@code null} when the registration date is absent.
258	     */
259	    default String formatFiscalYear(Owner owner) {
260	        if (owner == null || owner.getRegistrationDate() == null) {
261	            return null;
262	        }
263	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
264	    }
265	
266	    /**
267	     * Returns the starting calendar year of the fiscal year (which starts on 1 July) that contains
268	     * the given date: the date's own year when it falls on or after 1 July, otherwise the previous
269	     * year.
270	     */
271	    private int fiscalYearStart(LocalDate date) {
272	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
273	    }
274	
275	    /**
276	     * Formats an owner's stored E.164 telephone for humans as the country code, a space, and the
277	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
278	     * The raw {@code telephone} value stays in E.164 form. Returns the stored value unchanged when it
279	     * is {@code null} or not a well-formed E.164 string (a {@code '+'} followed by digits).
280	     */
281	    default String formatTelephoneDisplay(Owner owner) {
282	        if (owner == null) {
283	            return null;
284	        }
285	        String telephone = owner.getTelephone();
286	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
287	            return telephone;
288	        }
289	        String digits = telephone.substring(1);
290	        int countryCodeLength = countryCodeLength(digits);
291	        String countryCode = digits.substring(0, countryCodeLength);
292	        String national = digits.substring(countryCodeLength);
293	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
294	        for (int i = 0; i < national.length(); i += 3) {
295	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
296	        }
297	        return grouped.toString();
298	    }
299	
300	    /**
301	     * Determines the length of the country-code segment of an E.164 number's digits (its digits
302	     * without the leading {@code '+'}): 1 for the NANP ({@code '+1'}) and 2 otherwise (e.g. Australia's
303	     * {@code '+61'}), mirroring the country codes the application normalises to.
304	     */
305	    private int countryCodeLength(String digits) {
306	        return digits.startsWith("1") ? 1 : 2;
307	    }
308	
309	    /**
310	     * Formats an owner's canonical self link as {@code "/api/owners/" + id} from the stored id.
311	     * Returns {@code null} when the owner or its id is absent, so the field is omitted from the
312	     * response.
313	     */
314	    default String formatSelfLink(Owner owner) {
315	        if (owner == null || owner.getId() == null) {
316	            return null;
317	        }
318	        return "/api/owners/" + owner.getId();
319	    }
320	
321	    /**
322	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
323	     */
324	    default String formatDisplayName(Owner owner) {
325	        if (owner == null) {
326	            return null;
327	        }
328	        return owner.getLastName() + ", " + owner.getFirstName();
329	    }
330	
331	    /**
332	     * Formats an owner's salutation as the title and last name separated by a single space
333	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title
334	     * is given (null or blank). Returns {@code null} when the owner is {@code null}.
335	     */
336	    default String formatSalutation(Owner owner) {
337	        if (owner == null) {
338	            return null;
339	        }
340	        String title = owner.getTitle();
341	        if (title == null || title.isBlank()) {
342	            return owner.getLastName();
343	        }
344	        return title + " " + owner.getLastName();
345	    }
346	
347	    /**
348	     * Formats an owner's initials as the upper-cased first letters of the first and last
349	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
350	     */
351	    default String formatInitials(Owner owner) {
352	        if (owner == null) {
353	            return null;
354	        }
355	        return initial(owner.getFirstName()) + initial(owner.getLastName());
356	    }
357	
358	    private String initial(String name) {
359	        if (name == null || name.isEmpty()) {
360	            return "";
361	        }
362	        return Character.toUpperCase(name.charAt(0)) + ".";
363	    }
364	
365	    Owner toOwner(OwnerDto ownerDto);
366	
367	    @Mapping(target = "id", ignore = true)
368	    @Mapping(target = "pets", ignore = true)
369	    Owner toOwner(OwnerFieldsDto ownerDto);
370	
371	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
372	
373	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
374	
375	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
376	        OwnerPageDto ownerPageDto = new OwnerPageDto();
377	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
378	        ownerPageDto.setPage(ownerPage.getNumber());
379	        ownerPageDto.setSize(ownerPage.getSize());
380	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
381	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
382	        return ownerPageDto;
383	    }
384	}
