        return digits.startsWith("1") ? 1 : 2;
    }

    /**
     * Formats an owner's canonical self link as {@code "/api/owners/" + id} from the stored id.
     * Returns {@code null} when the owner or its id is absent, so the field is omitted from the
     * response.
     */
